#include <bits/stdc++.h>
using namespace std;

string solve(const vector<string>& grid, int r, int c, int size) {
    char first = grid[r][c];
    bool same = true;

    for (int i = r; i < r + size && same; ++i) {
        for (int j = c; j < c + size; ++j) {
            if (grid[i][j] != first) {
                same = false;
                break;
            }
        }
    }

    if (same) {
        return string(1, first);
    }

    int half = size / 2;
    return "("
         + solve(grid, r, c, half)
         + solve(grid, r, c + half, half)
         + solve(grid, r + half, c, half)
         + solve(grid, r + half, c + half, half)
         + ")";
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    vector<string> grid(n);
    for (int i = 0; i < n; ++i) {
        cin >> grid[i];
    }

    cout << solve(grid, 0, 0, n) << '\n';

    return 0;
}
